  // What each Round 1 grant was approved for, and where, from the public grant pages on nsw.gov.au (Category 1 and 2
  // recipients, extracted 12 Nov 2026). Matched to the grants above by amount and recipient name.
  const grantDetails = [{"r":"Coffs Harbour Snappers Rugby Union Club","a":112348,"d":"This project will upgrade existing changerooms to modern, compliant standards, improving accessibility, safety and inclusivity. The works will enhance the rugby experience for players, referees, coaches and volunteers, increase facility utilisation, and support equitable participation growth across junior, female and under-represented groups in the community.","loc":"Toormina 2452","on":"May 2026"},{"r":"Coonamble Shire Council","a":135200,"d":"The project will deliver lighting, scoreboard and changeroom upgrades at Gulargambone Sportsground in Central West NSW. Upgrades will enable vital nighttime training for Rugby Union as well as and the ability to host exhibition games, improving participation, facilities, and utilisation for local players, clubs and the wider community.","loc":"Gulargambone 2828","on":"May 2026"},{"r":"Cumberland Council","a":150000,"d":"This project delivers a modern, universally designed amenities building with accessible change rooms, showers, seating, and toilets. Located beside the existing facilities, it will significantly improve infrastructure and support increased participation of women and girls at the grounds.","loc":"Holroyd 2142","on":"May 2026"},{"r":"Emus Rugby Club Limited","a":87628,"d":"This project benefits Orange Emus’ 500+ junior and senior players by upgrading Field 2 to high-performance 1200W LED sports lighting. The upgrade will increase safe night-time training and competition capacity, improve player visibility and safety, and reduce the club’s energy consumption and ongoing maintenance costs.","loc":"Orange 2800","on":"May 2026"},{"r":"Glen Innes Elks Rugby Union Football Club","a":108626,"d":"The “Rugby Park” playing surface is on reactive black soil and is in a poor state. To address this the club has relevelled and resown the field to good results. There is no irrigation on the field and the work carried out will only last as long as it rains","loc":"Glen Innes 2370","on":"May 2026"},{"r":"Goulburn Rugby Union Football Club Incorporated","a":49025,"d":"Goulburn Rugby has 2 Mens teams and 1 Female team - with 1 set of change rooms fitted out with male infrastructure. Funding will be used to replace the existing male infrastructure with gender neutral options to support the growth and development of Womens rugby in Goulburn.","loc":"Goulburn 2580","on":"May 2026"},{"r":"Inverell Rugby Club","a":150000,"d":"The project involves upgrading field lighting to provide safe, secure, energy-efficient lighting for evening training and games. This upgrade will enhance player safety, extend usable hours, and support greater community access to sport and recreation. This will benefit all ages from 4-100 years, men and women who enjoy the game.","loc":"Inverell 2360","on":"May 2026"},{"r":"Manly Rugby Football Club","a":81387,"d":"The Keirle Park changeroom refurbishment will deliver inclusive, female-friendly facilities. The current amenities lack hot water, basic privacy, and fail contemporary standards. Upgrades will provide private showers, reliable hot and cold water, and accessible amenities, removing participation barriers and supporting growth in women’s rugby.","loc":"Manly 2095","on":"May 2026"},{"r":"Mid-Western Regional Council","a":150000,"d":"This project will deliver an upgraded, inclusive public address (PA) system at Glen Willow Regional Sporting Complex, benefiting players, officials, volunteers and spectators. Council will install a centralised PA control system with connected fixed speakers to improve communication, safety and accessibility, increasing participation, facility utilisation and the overall Rugby experience.","loc":"Putta Bucca 2850","on":"May 2026"},{"r":"Muswellbrook Shire Council","a":103565,"d":"Upgrade of Highbrook Sports Field amenities including female-friendly change room remodel, replacement of plumbing fixtures, ceiling repairs and waterproofing, internal and external painting of amenities and canteen, installation of compliant disabled facilities, and associated demolition, plumbing, tiling and finishing works to improve functionality, accessibility and presentation.","loc":"Muswellbrook 2333","on":"May 2026"},{"r":"Orange City Rugby Club Inc","a":150000,"d":"Removing our 60-year-old demountable toilet block and replacing it with new male amenities. With the addition of the referee's change room, new office, and new store room. When the toilet block goes out of commission, we would have to turn our new women's toilets into a unisex block.","loc":"Orange 2800","on":"May 2026"},{"r":"Port Macquarie-Hastings Council","a":105553,"d":"Council will install subsurface drainage to Field 5 at Stuart Park to improve turf performance, safety and resilience to wet weather. The upgrade will reduce cancellations, increase seasonal utilisation and support inclusive rugby participation for the Port Macquarie Pirates and the Port Macquarie Junior Rugby Union Competition.","loc":"Port Macquarie 2444","on":"May 2026"},{"r":"Sutherland Shire Council","a":150000,"d":"The project will deliver an integrated upgrade to the playing surface, drainage and lighting at John Dwyer Reserve. The works will improve safety, surface resilience and all-weather performance, increase available playing hours, and enhance the rugby experience for players, officials and spectators through a more reliable, compliant community facility.","loc":"Caringbah South 2229","on":"May 2026"},{"r":"Temora Rugby Union Football Club Inc.","a":41315,"d":"Development of a multi-purpose training, storage and function space facility. It will benefit all club members (men, women, junior boys and girls, referees and Old Boys - including First Nations and Pasifika groups). It will be used for training, storage of rugby gear, and to support the hosting of functions/events.","loc":"Temora 2666","on":"May 2026"},{"r":"Wakehurst Rugby Club","a":55405,"d":"Wakehurst Rugby Club will refurbish existing change facilities to deliver six private shower and change cubicles, two accessible cubicles and a dedicated Match Official facility. The project improves dignity, safeguarding and accessibility while supporting female participation growth and increased community use ahead of the 2027 Rugby World Cup.","loc":"Belrose 2085","on":"May 2026"},{"r":"Warren Shire Council","a":31018,"d":"This project upgrades key facilities at Victoria Park Precinct to improve safety, player recovery and welfare. Works include hot water upgrades","loc":"Ravenswood 2824","on":"May 2026"},{"r":"Woollahra Colleagues Rugby Union Football Club","a":150000,"d":"WCRUFC have 11 teams including 6 mens, 1 womens, 2 colts and 2 inclusive teams. Our home ground is WO2/3 which suffers from poor drainage causing a high number of closures. Other users include Cranbrook junior school, Bays junior rugby and Easts Rugby. in 2025 we had 329 registered players.","loc":"Rose Bay 2029","on":"May 2026"},{"r":"Central West Rugby Union Incorporated","a":16000,"d":"Central West Rugby Union will employ a part-time Referee Support and Development Officer to recruit, accredit and mentor new referees. The project will improve first-year retention, reduce referee shortages and strengthen match delivery capacity across 38 clubs, supporting sustainable participation growth for 3,800 players.","loc":"Orange 2800","on":"May 2026"},{"r":"Coffs Harbour Junior Rugby Union","a":5500,"d":"This initiative strengthens safe junior rugby participation across U8–U12 while accelerating girls rugby growth in regional NSW. It will deliver upgraded contact safety equipment, female coach accreditation and targeted girls activation sessions, improving inclusion, coaching capability and long-term participation pathways in the lead-up to the 2027 Rugby World Cup.","loc":"Toormina 2452","on":"May 2026"},{"r":"Coffs Harbour Snappers Rugby Union Club","a":12500,"d":"This initiative will benefit junior, women’s and senior rugby players by upskilling local coaches and delivering evidence-based health, injury-prevention and performance activities. Through accredited coaching courses and allied-health education and testing, we expect safer participation, stronger coaching capability, reduced injury risk and improved long-term player development.","loc":"Toormina 2452","on":"May 2026"},{"r":"Country Rugby Union of New South Wales Ltd","a":20000,"d":"NSWCRU will deliver a structured Athlete Physical Development Program for 20-30 regional representative players aged 14–16 (50/50 Male/Female). (In the first year) The program provides strength, speed and injury prevention training, athlete education and monitoring to improve performance, reduce injury risk and prepare participants for 2027 high performance team selection.","loc":"Scone 2337","on":"May 2026"},{"r":"Forbes Rugby Union Club","a":15477,"d":"The project will benefit women and girls (including First Nations and Pasifika groups) by providing greater access to rugby union competitions and skilled coaches, as well as equipment and other supporting resources. The project will also develop Coaches to support women and girls teams, including developing a female coach.","loc":"Forbes 2871","on":"May 2026"},{"r":"Illawarra District Rugby Union","a":12080,"d":"Establish a 12-week Illawarra Junior Rugby Academy program at Wollongong University for 140 players (70 boys and 70 girls, aged U12s – U18s) from Illawarra Clubs. The Academy will strengthen participation, retention and female pathways and provide a clear rugby union alternative to programs for other codes in the region.","loc":"Keiraville 2500","on":"May 2026"},{"r":"Illawarra District Rugby Union","a":20000,"d":"Expansion of the Illawarra Friday Night Junior Rugby 7s competition across three rugby club venues, introducing new U17 boys and girls divisions and increasing girls teams in existing age groups. It also integrates Sense Rugby, an all-abilities program delivered by Occupational Therapists.","loc":"Woonona 2517","on":"May 2026"},{"r":"Maitland Junior Rugby Union","a":5100,"d":"Expand girls and junior rugby participation by developing a structured coaching pathway. New coaches will gain Level 1 accreditation, experienced coaches will be upskilled to Level 2, and a mentoring model will strengthen coaching quality. The program will build sustainable coaching capacity and improve participation, retention, and player experience.","loc":"Lorn 2320","on":"May 2026"},{"r":"New England Junior Rugby Union","a":20000,"d":"A weekly centralised youth rugby program in Armidale for U14/U16/U18 boys and girls, with targeted inclusion for women and girls, First Nations youth and regional participants, plus youth referee and volunteer development to strengthen long-term pathways.","loc":"Armidale 2350","on":"May 2026"},{"r":"New South Wales Country Referees Association","a":8000,"d":"NSW Country Match Official Recruitment and Education Program. This initiative is designed to recruit, educate and accredit Match Officials throughout Rural and Regional NSW, thus servicing our participants and ensuring sustainability beyond 2026. The primary focus will be on recruitment and education of Volunteer Match Officials.","loc":"Daceyville 2032","on":"May 2026"},{"r":"NSW Junior Rugby Union","a":20000,"d":"The NSW Juniors All Nations 7s Cup is a multicultural youth Rugby 7s tournament held at Eric Tweedale Stadium, Granville. It brings together boys and girls teams (U13, U15, U17) representing diverse cultural communities. The event celebrates inclusion, strengthens social cohesion, and increases participation through an exciting festival-style competition.","loc":"Merrylands 2160","on":"May 2026"},{"r":"NSW Suburban Rugby Union Inc","a":17058,"d":"This project will increase participation by offering rugby to under-represented groups who may feel unable/unsuited to play and who felt excluded. This project is aimed at women, men over 35, players U85kgs, Western Sydney residents, and all those unable to participate on a Saturday, when rugby has been traditionally offered.","loc":"Merrylands 2160","on":"May 2026"},{"r":"Southern Inland Rugby Referees Association (SIRRA) Inc","a":14410,"d":"This project aims to increase the player to match official ratio and increase the percentage of female, Pacifica and First Nations match official participants. The design has a focus on inclusivity, providing individual support and experiences that participants can enjoy together. Pathways from Referee Ready to Level 1 accreditation","loc":"Bourkelands 2650","on":"May 2026"},{"r":"Southern Inland Rugby Union (SIRU)","a":9474,"d":"The Get into Rugby Program will be a 3-year, non-contact “Get into Rugby” program for 4–7-year-olds across Grenfell, Wagga Wagga, and Albury. Delivered in 4-week blocks, it builds skills, confidence, and pathways into junior club rugby, targeting girls and First Nations children, with a staged transition to club-led delivery","loc":"Wagga Wagga 2650","on":"May 2026"},{"r":"Sydney Junior Rugby Union","a":18750,"d":"SJRU will support clubs to establish Get into Rugby – Walla programs for U4–U5 players, building early engagement and preparing children for Tri-Tag at U6. SJRU provides coaches, equipment, and volunteer training, developing club-based activators and creating sustainable, self-run entry pathways that grow participation and strengthen grassroots rugby.","loc":"Daceyville 2032","on":"May 2026"},{"r":"Sydney Junior Rugby Union","a":15000,"d":"Sydney Junior Rugby Union will provide targeted coaching resources to affiliated clubs to support accreditation of U10–U15 coaches. The initiative will subsidise course access, deliver mentoring, and provide structured development support, ensuring coaches are appropriately qualified and players receive safe, high-quality coaching aligned with national standards.","loc":"Daceyville 2032","on":"May 2026"},{"r":"Sydney Women's Rugby Union","a":14601,"d":"Sydney Women's Rugby Union will deliver a 7-round Tri-Tag non-contact competition (September-March) for 50-70 new participants, with activation at the Chikarovski Cup Super Round in July. Fifteen female coaches receive World Rugby Level 1 accreditation. This creates accessible entry pathways, strengthening Sydney women's rugby ahead of RWC 2027.","loc":"Rose Bay 2029","on":"May 2026"},{"r":"Western Plains Junior Rugby Union CLub","a":20000,"d":"WPJRU Under 12's Development Program is a year-round junior rugby and personal development initiative based at Warren Sports Complex. Led by the WPJRU and delivered in partnership with NSW Rugby Union. A comprehensive, year-round development program focused on establishing and strengthening Western Plains Under 12s structures building towards Saturday Competition.","loc":"Ravenswood 2824","on":"May 2026"},{"r":"Western Plains Junior Rugby Union CLub","a":20000,"d":"The Western Plains Junior Rugby Coach Development Program will deliver four accredited community coaching courses across regional Western NSW. The program will upskill 80 local coaches, strengthen volunteer capacity, support First Nations participation, and improve junior player retention by increasing the quality, safety and consistency of grassroots rugby delivery.","loc":"Bourke 2840","on":"May 2026"},{"r":"Yamba Buccaneers Rugby Club","a":15000,"d":"The Clarence Valley Rugby 7s Schools’ Competition will benefit primary school students in Years 3–6, particularly girls and first-time participants. The initiative includes pre-competition coaching clinics and a four-week after-school 7s competition. Outcomes include increased junior and female participation, improved skills, and strengthened pathways into local community rugby.","loc":"Yamba 2464","on":"May 2026"}];
  const norm = s => String(s).toLowerCase().replace(/[^a-z]/g, '');
  for (const g of grants) {
    const m = grantDetails.find(x => x.a === g.amount && (norm(x.r).includes(norm(g.recipient).slice(0, 8)) || norm(g.recipient).includes(norm(x.r).slice(0, 8))));
    const only = grantDetails.filter(x => x.a === g.amount); // names differ (e.g. 'Manly RFC'): a unique amount is enough
    const hit = m || (only.length === 1 ? only[0] : null);
    if (hit) Object.assign(g, { approvedFor: hit.d, projectLocation: hit.loc, approvedOn: hit.on });
  }

  // Public record of Legacy funding beyond the Round 1 club grants (Office of Sport Grants 2025/26, nsw.gov.au).
  const publicRecord = {
    nswruLegacyGrant: { amount: 5187000, approved: 'December 2025', term: '30/06/2029', what: 'NSW Rugby World Cup Legacy Program (NSW Rugby-led plan): capacity and capability across the rugby network; play, infrastructure, workforce and diverse communities.', source: 'https://www.nsw.gov.au/grants-and-funding/office-of-sport-grants-2025/26' },
    equipmentProgram: { amount: 513000, approved: 'July 2026', term: '30/06/2027', what: 'NSW Rugby Union - Rugby World Cup Equipment Program: statewide procurement and distribution of community rugby equipment to clubs and referee associations.', status: 'Not counted as Legacy until NSW Rugby confirms it is the Legacy equipment component (the plan showed $350k).', source: 'https://www.nsw.gov.au/grants-and-funding/office-of-sport-grants-2025/26' },
    round1Demand: { cat1: { funded: 17, applied: 55 }, cat2: { funded: 20, applied: 53 }, source: 'Category 1 and 2 recipient pages, nsw.gov.au (Applications approved / received)' },
  };

  // Grants that are not part of the program, left out everywhere (Analytics.allGrants), even if an uploaded file lists them.
  const excludedGrants = [
    { match: /woonona shamrocks/i, reason: 'Did not accept the Round 1 offer, as only part funding was offered (NSW Rugby, Nov 2026).' },
  ];

